var energy = energia.value; // Produção do dia em kWh
var irrad = POA.value;     // Irradiação do dia em Wh/m²
var temp = Module1.value;  // Temperatura instantânea do módulo em °C
var kwp = capacity.value;  // Potência pico do sistema em kW
var coef_temp = -0.0030;   // Coeficiente de temperatura (%/°C)
expectedEnergy = expected.value; // Energia esperada 

// Corrigir energia para Wh
var energyWh = energy * 1000; // Convertendo de kWh para Wh

// Performance Ratio com validação
var PR = 0;
if (expectedEnergy > 0) {
    PR = energyWh / (expectedEnergy * 1000); // Energia Esperada em Wh
    if (PR > 1) {
        PR = 1; // Força o valor para 100% se passar de 100%
    }
}

